import csv
import io

_DECIMAL_DIGITS = set('0123456789')


def _row_to_item(row):
    if None in row and row[None]:
        raise ValueError('row has too many fields')
    values = []
    for key in ('sku', 'name', 'qty'):
        value = row.get(key)
        if not isinstance(value, str):
            raise ValueError('row must contain sku, name and qty')
        values.append(value.strip())
    sku, name, qty = values
    if not sku:
        raise ValueError('sku must not be empty')
    if not name:
        raise ValueError('name must not be empty')
    if not qty or any(ch not in _DECIMAL_DIGITS for ch in qty):
        raise ValueError('qty must be a nonnegative integer')
    return {'sku': sku, 'name': name, 'qty': int(qty)}


def import_text(text, store, dry_run=False):
    try:
        rows = list(csv.DictReader(io.StringIO(text)))
    except csv.Error as exc:
        raise ValueError('invalid CSV row') from exc
    # Validate every row before committing any changes.
    items = [_row_to_item(row) for row in rows]

    state = {key: value.copy() for key, value in store.items.items()}
    result = {'created': 0, 'updated': 0, 'unchanged': 0, 'changes': []}
    for item in items:
        before = state.get(item['sku'])
        if before == item:
            result['unchanged'] += 1
            continue
        result['created' if before is None else 'updated'] += 1
        result['changes'].append({'sku': item['sku'], 'before': before, 'after': item})
        state[item['sku']] = item

    if not dry_run:
        for change in result['changes']:
            store.put(change['after'])
    return result

